package com.example.wordstore.domain.scheduling

import kotlin.math.E
import kotlin.math.floor
import kotlin.math.max
import kotlin.math.min
import kotlin.math.pow
import kotlin.random.Random

/**
 * FSRS-6 scheduler, ported from py-fsrs 6.3.2 (MIT, see third_party/licenses/MIT-py-fsrs.txt).
 *
 * Fsrs6SchedulerTest replays histories generated by the real py-fsrs against this class.
 *
 * One deliberate difference: fuzz is seeded from the card ID and repetition count rather than a
 * global RNG, so [preview] returns exactly the interval that [review] will apply.
 */
class Fsrs6Scheduler(
    private val parameters: List<Double> = DEFAULT_PARAMETERS,
    private val desiredRetention: Double = 0.9,
    private val learningSteps: List<Long> = listOf(1 * MINUTE, 10 * MINUTE),
    private val relearningSteps: List<Long> = listOf(10 * MINUTE),
    private val maximumInterval: Int = 36500,
    private val enableFuzz: Boolean = true
) : SpacedRepetitionScheduler {

    override val algorithmVersion: String = ALGORITHM_VERSION

    private val decay = -parameters[20]
    private val factor = 0.9.pow(1 / decay) - 1

    init {
        require(parameters.size == DEFAULT_PARAMETERS.size) {
            "Expected ${DEFAULT_PARAMETERS.size} parameters, got ${parameters.size}"
        }
    }

    override fun retrievability(memory: CardMemory, nowMillis: Long): Double {
        val lastReview = memory.lastReviewAt ?: return 0.0
        val stability = memory.stability ?: return 0.0
        val elapsedDays = max(0L, wholeDays(nowMillis - lastReview))
        return (1 + factor * elapsedDays / stability).pow(decay)
    }

    override fun review(memory: CardMemory, rating: Rating, nowMillis: Long): ReviewOutcome {
        val elapsedDays = memory.lastReviewAt?.let { wholeDays(nowMillis - it) }
        val result = when (memory.state) {
            CardState.NEW, CardState.LEARNING -> reviewLearning(memory, rating, nowMillis, elapsedDays)
            CardState.REVIEW -> reviewReview(memory, rating, nowMillis, elapsedDays)
            CardState.RELEARNING -> reviewRelearning(memory, rating, nowMillis, elapsedDays)
        }

        val interval = if (enableFuzz && result.state == CardState.REVIEW) {
            fuzzed(result.interval, memory)
        } else {
            result.interval
        }

        val updated = memory.copy(
            state = result.state,
            step = result.step,
            stability = result.stability,
            difficulty = result.difficulty,
            dueAt = nowMillis + interval,
            lastReviewAt = nowMillis,
            reps = memory.reps + 1,
            lapses = memory.lapses + if (memory.state == CardState.REVIEW && rating == Rating.AGAIN) 1 else 0
        )
        return ReviewOutcome(
            rating = rating,
            memory = updated,
            intervalMillis = interval,
            elapsedMillis = memory.lastReviewAt?.let { nowMillis - it } ?: 0L
        )
    }

    private class Step(
        val state: CardState,
        val step: Int?,
        val stability: Double,
        val difficulty: Double,
        val interval: Long
    )

    private fun reviewLearning(memory: CardMemory, rating: Rating, now: Long, elapsedDays: Long?): Step {
        val currentStability = memory.stability
        val currentDifficulty = memory.difficulty
        val stability: Double
        val difficulty: Double
        when {
            currentStability == null || currentDifficulty == null -> {
                stability = initialStability(rating)
                difficulty = clampDifficulty(initialDifficulty(rating))
            }
            elapsedDays != null && elapsedDays < 1 -> {
                stability = shortTermStability(currentStability, rating)
                difficulty = nextDifficulty(currentDifficulty, rating)
            }
            else -> {
                stability = nextStability(currentDifficulty, currentStability, retrievability(memory, now), rating)
                difficulty = nextDifficulty(currentDifficulty, rating)
            }
        }
        return advanceThroughSteps(
            steps = learningSteps,
            activeState = CardState.LEARNING,
            currentStep = memory.step ?: 0,
            rating = rating,
            stability = stability,
            difficulty = difficulty
        )
    }

    private fun reviewReview(memory: CardMemory, rating: Rating, now: Long, elapsedDays: Long?): Step {
        val currentStability = requireNotNull(memory.stability)
        val currentDifficulty = requireNotNull(memory.difficulty)
        val stability = if (elapsedDays != null && elapsedDays < 1) {
            shortTermStability(currentStability, rating)
        } else {
            nextStability(currentDifficulty, currentStability, retrievability(memory, now), rating)
        }
        val difficulty = nextDifficulty(currentDifficulty, rating)

        return if (rating == Rating.AGAIN && relearningSteps.isNotEmpty()) {
            Step(CardState.RELEARNING, 0, stability, difficulty, relearningSteps[0])
        } else {
            Step(CardState.REVIEW, null, stability, difficulty, days(nextInterval(stability)))
        }
    }

    private fun reviewRelearning(memory: CardMemory, rating: Rating, now: Long, elapsedDays: Long?): Step {
        val currentStability = requireNotNull(memory.stability)
        val currentDifficulty = requireNotNull(memory.difficulty)
        val stability = if (elapsedDays != null && elapsedDays < 1) {
            shortTermStability(currentStability, rating)
        } else {
            nextStability(currentDifficulty, currentStability, retrievability(memory, now), rating)
        }
        val difficulty = nextDifficulty(currentDifficulty, rating)
        return advanceThroughSteps(
            steps = relearningSteps,
            activeState = CardState.RELEARNING,
            currentStep = requireNotNull(memory.step),
            rating = rating,
            stability = stability,
            difficulty = difficulty
        )
    }

    private fun advanceThroughSteps(
        steps: List<Long>,
        activeState: CardState,
        currentStep: Int,
        rating: Rating,
        stability: Double,
        difficulty: Double
    ): Step {
        fun graduate() = Step(CardState.REVIEW, null, stability, difficulty, days(nextInterval(stability)))

        // Covers a card scheduled earlier with more steps than the scheduler has now.
        if (steps.isEmpty() || (currentStep >= steps.size && rating != Rating.AGAIN)) return graduate()

        return when (rating) {
            Rating.AGAIN -> Step(activeState, 0, stability, difficulty, steps[0])
            Rating.HARD -> {
                val interval = when {
                    currentStep == 0 && steps.size == 1 -> (steps[0] * 1.5).toLong()
                    currentStep == 0 -> (steps[0] + steps[1]) / 2
                    else -> steps[currentStep]
                }
                Step(activeState, currentStep, stability, difficulty, interval)
            }
            Rating.GOOD ->
                if (currentStep + 1 == steps.size) {
                    graduate()
                } else {
                    Step(activeState, currentStep + 1, stability, difficulty, steps[currentStep + 1])
                }
            Rating.EASY -> graduate()
        }
    }

    private fun clampDifficulty(difficulty: Double) = difficulty.coerceIn(MIN_DIFFICULTY, MAX_DIFFICULTY)

    private fun clampStability(stability: Double) = max(stability, STABILITY_MIN)

    private fun initialStability(rating: Rating) = clampStability(parameters[rating.value - 1])

    private fun initialDifficulty(rating: Rating) =
        parameters[4] - E.pow(parameters[5] * (rating.value - 1)) + 1

    private fun nextInterval(stability: Double): Int {
        val raw = (stability / factor) * (desiredRetention.pow(1 / decay) - 1)
        return min(max(Math.rint(raw).toInt(), 1), maximumInterval)
    }

    private fun shortTermStability(stability: Double, rating: Rating): Double {
        var increase = E.pow(parameters[17] * (rating.value - 3 + parameters[18])) *
            stability.pow(-parameters[19])
        if (rating != Rating.AGAIN) increase = max(increase, 1.0)
        return clampStability(stability * increase)
    }

    private fun nextDifficulty(difficulty: Double, rating: Rating): Double {
        val delta = -(parameters[6] * (rating.value - 3))
        val damped = difficulty + (10.0 - difficulty) * delta / 9.0
        val reverted = parameters[7] * initialDifficulty(Rating.EASY) + (1 - parameters[7]) * damped
        return clampDifficulty(reverted)
    }

    private fun nextStability(difficulty: Double, stability: Double, retrievability: Double, rating: Rating): Double =
        clampStability(
            if (rating == Rating.AGAIN) {
                nextForgetStability(difficulty, stability, retrievability)
            } else {
                nextRecallStability(difficulty, stability, retrievability, rating)
            }
        )

    private fun nextForgetStability(difficulty: Double, stability: Double, retrievability: Double): Double {
        val longTerm = parameters[11] *
            difficulty.pow(-parameters[12]) *
            ((stability + 1).pow(parameters[13]) - 1) *
            E.pow((1 - retrievability) * parameters[14])
        val shortTerm = stability / E.pow(parameters[17] * parameters[18])
        return min(longTerm, shortTerm)
    }

    private fun nextRecallStability(difficulty: Double, stability: Double, retrievability: Double, rating: Rating): Double {
        val hardPenalty = if (rating == Rating.HARD) parameters[15] else 1.0
        val easyBonus = if (rating == Rating.EASY) parameters[16] else 1.0
        return stability * (
            1 + E.pow(parameters[8]) *
                (11 - difficulty) *
                stability.pow(-parameters[9]) *
                (E.pow((1 - retrievability) * parameters[10]) - 1) *
                hardPenalty *
                easyBonus
            )
    }

    private fun fuzzed(interval: Long, memory: CardMemory): Long {
        val intervalDays = wholeDays(interval).toInt()
        if (intervalDays < 3) return interval

        val range = fuzzRange(intervalDays)
        val draw = Random(memory.cardId * 31 + memory.reps).nextDouble()
        val fuzzedDays = Math.rint(draw * (range.last - range.first + 1) + range.first).toInt()
        return days(min(fuzzedDays, maximumInterval))
    }

    /** The inclusive range of days an [intervalDays] interval can fuzz into. */
    fun fuzzRange(intervalDays: Int): IntRange {
        var delta = 1.0
        for ((start, end, rate) in FUZZ_RANGES) {
            delta += rate * max(min(intervalDays.toDouble(), end) - start, 0.0)
        }
        val high = min(Math.rint(intervalDays + delta).toInt(), maximumInterval)
        val low = min(max(2, Math.rint(intervalDays - delta).toInt()), high)
        return low..high
    }

    private fun wholeDays(millis: Long): Long = floor(millis.toDouble() / DAY).toLong()

    private fun days(count: Int): Long = count * DAY

    companion object {
        const val ALGORITHM_VERSION = "fsrs-6"

        const val MINUTE = 60_000L
        const val DAY = 86_400_000L

        private const val STABILITY_MIN = 0.001
        private const val MIN_DIFFICULTY = 1.0
        private const val MAX_DIFFICULTY = 10.0

        val DEFAULT_PARAMETERS = listOf(
            0.212, 1.2931, 2.3065, 8.2956, 6.4133, 0.8334, 3.0194, 0.001, 1.8722, 0.1666,
            0.796, 1.4835, 0.0614, 0.2629, 1.6483, 0.6014, 1.8729, 0.5425, 0.0912, 0.0658,
            0.1542
        )

        private val FUZZ_RANGES = listOf(
            Triple(2.5, 7.0, 0.15),
            Triple(7.0, 20.0, 0.1),
            Triple(20.0, Double.POSITIVE_INFINITY, 0.05)
        )
    }
}
